do $$declare x jsonb;f uuid;h jsonb;pkg uuid;rev integer;grants jsonb;foreign_factory uuid;begin
 select t.x into x from m3c_test.context t;f:=(x->>'factory')::uuid;
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 perform m3c_test.fails(format('select public.lean_read(%L,''{"mode":"entries"}'')',f),'42501');
 perform m3c_test.fails(format('select public.quality_read(%L,''{"mode":"board"}'')',f),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 insert into public.user_permissions(factory_id,user_id,module,action) values(f,(x->>'viewer')::uuid,'quality','view');
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 h:=public.quality_read(f,jsonb_build_object('mode','board','entry',x->>'entry'));
 perform m3c_test.ok(h#>>'{rows,0,scrap,production_scrap_kg}'='2.1234567890123456789' and h#>>'{rows,0,scrap_evidence}' is null,'Quality-only sees operational KG without Lean evidence or pending proposals');
 select id into foreign_factory from public.factories where id<>f order by id limit 1;
 perform m3c_test.fails(format('select public.quality_read(%L,''{"mode":"board"}'')',foreign_factory),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 pkg:=public.save_permission_package(f,gen_random_uuid(),'{"name":"Local M3C reviewer","name_ar":"مراجع محلي"}','[{"module":"factory","action":"view"},{"module":"lean","action":"view"},{"module":"lean","action":"edit"}]',0);
 perform public.set_member_permission_packages(f,(x->>'viewer')::uuid,array[pkg],array[]::uuid[]);
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 h:=public.lean_read(f,'{"mode":"pending"}');
 perform m3c_test.ok((h->>'total')::int>=1,'effective package grants allow existing review reader');
 perform m3c_test.fails(format('select public.production_correction_command(%L,''approve'',%L,%L)',f,jsonb_build_object('id',gen_random_uuid()),gen_random_uuid()),'42501');
 perform m3c_test.fails(format('select public.lean_read(%L,''{"mode":"entries"}'')',foreign_factory),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 select revision into rev from public.permission_packages where id=pkg;
 perform public.save_permission_package(f,pkg,'{"name":"Local M3C reviewer","name_ar":"مراجع محلي"}','[{"module":"factory","action":"view"},{"module":"lean","action":"view"}]',rev);
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 perform m3c_test.fails(format('select public.lean_read(%L,''{"mode":"pending"}'')',f),'42501');
 perform m3c_test.ok(not has_function_privilege('authenticated','private.lean_command_before_m3c(uuid,uuid,text,jsonb)','EXECUTE') and not has_function_privilege('authenticated','private.quality_read_before_m3c(uuid,jsonb)','EXECUTE'),'old delegates remain revoked');
 perform m3c_test.ok(not has_function_privilege('authenticated','private.lean_window_occurrences(uuid,timestamptz,timestamptz)','EXECUTE'),'unprotected occurrence helper inaccessible');
 perform m3c_test.ok(not has_table_privilege('authenticated','private.production_correction_requests','SELECT'),'pending correction details stay private');
end$$;
set role anon;
do $$begin begin perform public.quality_read(gen_random_uuid(),'{}');raise exception 'Expected anonymous denial';exception when insufficient_privilege then null;end;begin perform public.lean_read(gen_random_uuid(),'{}');raise exception 'Expected anonymous denial';exception when insufficient_privilege then null;end;end$$;
reset role;
select m3c_test.ok(true,'actual anonymous execution denied');
select count(*) as cumulative_consumer_assertions from m3c_test.checks;
